class Solution {
public:
    vector<string> sortFeatures(vector<string>& features, vector<string>& responses) {
        vector<unordered_set<string>> tokens;
        for (auto& r : responses) {
            stringstream ss(r);
            unordered_set<string> st;
            string w;
            while (ss >> w) st.insert(w);
            tokens.push_back(move(st));
        }
        vector<int> idx(features.size());
        iota(idx.begin(), idx.end(), 0);
        sort(idx.begin(), idx.end(), [&](int a, int b) {
            int ca = 0, cb = 0;
            for (auto& t : tokens) {
                ca += t.count(features[a]);
                cb += t.count(features[b]);
            }
            return ca != cb ? ca > cb : a < b;
        });
        vector<string> res;
        for (int i : idx) res.push_back(features[i]);
        return res;
    }
};

