class Solution {
    public String[] sortFeatures(String[] features, String[] responses) {
        int n = features.length;
        Set<String>[] tokens = new HashSet[responses.length];
        for (int i = 0; i < responses.length; i++) {
            tokens[i] = new HashSet<>(Arrays.asList(responses[i].split(" ")));
        }
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> {
            int ca = 0, cb = 0;
            for (Set<String> t : tokens) {
                if (t.contains(features[a])) ca++;
                if (t.contains(features[b])) cb++;
            }
            return ca != cb ? cb - ca : a - b;
        });
        String[] res = new String[n];
        for (int i = 0; i < n; i++) res[i] = features[idx[i]];
        return res;
    }
};

