class Solution {
public:
    vector<string> sortFeatures(vector<string>& features, vector<string>& responses) {
        unordered_map<string, int> cnt;
        for (auto& r : responses) {
            stringstream ss(r);
            unordered_set<string> seen;
            string w;
            while (ss >> w) seen.insert(w);
            for (auto& s : seen) cnt[s]++;
        }
        auto get = [&](const string& f) {
            auto it = cnt.find(f);
            return it == cnt.end() ? 0 : it->second;
        };
        vector<int> idx(features.size());
        iota(idx.begin(), idx.end(), 0);
        stable_sort(idx.begin(), idx.end(),
                    [&](int a, int b) { return get(features[a]) > get(features[b]); });
        vector<string> res;
        for (int i : idx) res.push_back(features[i]);
        return res;
    }
};

