class Solution {
    public String[] sortFeatures(String[] features, String[] responses) {
        Map<String, Integer> cnt = new HashMap<>();
        for (String r : responses) {
            Set<String> seen = new HashSet<>(Arrays.asList(r.split(" ")));
            for (String w : seen) cnt.merge(w, 1, Integer::sum);
        }
        Integer[] idx = new Integer[features.length];
        for (int i = 0; i < features.length; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> {
            int ca = cnt.getOrDefault(features[a], 0), cb = cnt.getOrDefault(features[b], 0);
            return ca != cb ? cb - ca : a - b;
        });
        String[] res = new String[features.length];
        for (int i = 0; i < features.length; i++) res[i] = features[idx[i]];
        return res;
    }
};

